import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ResourcePacksReadyForValidation{}
EMPTY = bytes.fromhex("")


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_resource_packs_ready_for_validation_is_packet_340(version):
    assert version.PACKETS[340] is version.ResourcePacksReadyForValidationPacket


def test_resource_packs_ready_for_validation_encodes_to_its_golden():
    assert bytes(v2225.ResourcePacksReadyForValidationPacket()) == EMPTY


def test_resource_packs_ready_for_validation_decodes_from_its_golden():
    assert (
        v2225.ResourcePacksReadyForValidationPacket.from_bytes(EMPTY) == v2225.ResourcePacksReadyForValidationPacket()
    )


def test_the_validation_ready_body_reads_none_of_the_byte_behind_it():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2225.ResourcePacksReadyForValidationPacket.from_bytes(b"\x01")
